import type { Shipment } from "./model.ts";

fn format_code(code: String) -> String {
  "便 " + code
}

export fn label(shipment: Shipment) -> String {
  match shipment {
    Waiting => "準備中",
    Shipped(code) => format_code(code),
  }
}

